head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vRowCount = 0;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05501.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_StartDd_onclick
 * @description img_StartDd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_StartDd_onclick = function(e) {
    try {
        popUpCalendar2(edt_StartDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.img_StartDd_onclick" });
    }
};

/**
 * @method
 * @name img_EndDd_onclick
 * @description img_EndDd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_EndDd_onclick = function(e) {
    try {
        popUpCalendar2(edt_EndDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.img_EndDd_onclick" });
    }
};

/**
 * @method
 * @name img_SaleDd_onclick
 * @description img_SaleDd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_SaleDd_onclick = function(e) {
    try {
        if (scwin.vRowCount === 0) return;

        popUpCalendar2(edt_SaleDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.img_SaleDd_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadError = function() {
    try {
        alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vRowCount = rowcount;
        if (rowcount === 0) return;
        grd_List.Redraw = false;

        // 합계추가
        let id = '';
        let vBndTotSalesSum = 0;
        let vRedmptAmtSum = 0;
        let vNetSaleAmtSum = 0;
        for (let i = 1; i <= dts_List.CountRow; i++) {
            // row pos
            if (i === 1) {

                id = dts_List.NameValue(i, 'BND_APPL_ID');
            }

            // 일별매출총액

            if (dts_List.NameValue(i, 'BND_TOT_SALES') === '') {
                vBndTotSalesSum += 0;
            } else {

                vBndTotSalesSum += parseInt($c.ut.replaceAll(dts_List.NameValue(i, 'BND_TOT_SALES'), ',', ''));
            }

            // 일중중도상환액

            if (dts_List.NameValue(i, 'REDMPT_AMT') === '') {
                vRedmptAmtSum += 0;
            } else {

                vRedmptAmtSum += parseInt($c.ut.replaceAll(dts_List.NameValue(i, 'REDMPT_AMT'), ',', ''));
            }

            // 일중중도상환액

            if (dts_List.NameValue(i, 'NET_SALE_AMT') === '') {
                vNetSaleAmtSum += 0;
            } else {

                vNetSaleAmtSum += parseInt($c.ut.replaceAll(dts_List.NameValue(i, 'NET_SALE_AMT'), ',', ''));
            }

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

        }

        dts_List.AddRow(); /*ORG SRC: dts_List.NameValue(dts_List.RowPosition, 'BND_APPL_ID') = '합계';*/ X = '합계'; /*ORG SRC: dts_List.NameValue(dts_List.RowPosition, 'BND_TOT_SALES') = addComma('' + vBndTotSalesSum);*/ X = $c.stf.addComma('' + vBndTotSalesSum); /*ORG SRC: dts_List.NameValue(dts_List.RowPosition, 'REDMPT_AMT') = addComma('' + vRedmptAmtSum);*/ X = $c.stf.addComma('' + vRedmptAmtSum); /*ORG SRC: dts_List.NameValue(dts_List.RowPosition, 'NET_SALE_AMT') = addComma('' + vNetSaleAmtSum);*/ X = $c.stf.addComma('' + vNetSaleAmtSum);

        dts_List.RowPosition = dts_List.NameValueRow("BND_APPL_ID", id);
        grd_List.Redraw = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        if (row > 0) {

            if ("가상장금액" === dts_List.NameValue(row, "BND_APPL_ID")) return;

            if ("합계" === dts_List.NameValue(row, "BND_APPL_ID")) return;

            txb_BndApplNo.setValue(dts_List.NameValue(row, "BND_APPL_ID"));

            edt_SaleDd.setValue(dts_List.NameValue(row, "SALE_DD"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.dts_List_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name btn_Update_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Update_onclick = function(e) {
    try {
        if (scwin.vRowCount === 0) return;
        if (txb_BndApplNo.getValue() === '') return;
        scwin.update();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05501.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        alert($c.stf.getMessageParam("MSG-0001"));
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05501.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 기관 데이터를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_SALE_DECL_DTL";
    url += "&queryId=lds.stf.bnsisuchg.select.listSaleDeclDtl";
    url += "&SCREN_ID=" + 'ULDSTF05501.gfm';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STD_CD=" + txb_StdCd.getValue();
    url += "&{P}V_BND_INST_CD=" + cmb_SaleInstCd.getValue();
    url += "&{P}V_START_DD=" + edt_StartDd.getValue();
    url += "&{P}V_END_DD=" + edt_EndDd.getValue();
    url += "&{P}V_BND_LIST_PROCS_TP_CD=" + txb_BndListProcsTpCd.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCombo
 * @description 콤보데이터를 설정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCombo = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_INFO";
    url += "&queryId=lds.stf.bnscommon.select.listSalesInst";
    url += "&SCREN_ID=" + 'ULDSTF05501.gfm';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_BND_LIST_PROCS_TP_CD=" + txb_BndListProcsTpCd.getValue();
    url += "&{P}V_ISU_CD=" + txb_StdCd.getValue();
    const sbmOptions = {
        id : "sbm_dts_SaleInst",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_SaleInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name update
 * @description 매추일을 수정한다.
 * @returns {void}
 * @hidden N
 */
scwin.update = function() {
    if (edt_SaleDd.getValue() === '') {
        alert('매출일을 입력하십시오.');
        return;
    }
    if (edt_SaleDd.getValue() >= scwin.vCurDate) {
        const vShowDate = scwin.vCurDate.substring(0, 4) + '.' + scwin.vCurDate.substring(4, 6) + '.' + scwin.vCurDate.substring(6, 8);
        alert('매출일을 ' + vShowDate + ' 보다 이전 일자로 입력하십시오.');
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "수정"))) return;
    let url = "/bns/IsuChgAmt.do?method=updateSaleDeclDtl";
    url += "&SCREN_ID=" + 'ULDSTF05501.gfm';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    let param = "BND_APPL_ID=" + txb_BndApplNo.getValue();
    param += ", BND_LIST_PROCS_TP_CD=" + txb_BndListProcsTpCd.getValue();
    param += ", SALE_DD=" + edt_SaleDd.getValue();
    trs_Save.Action = $c.lce.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;

    trs_Save.Post();
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {

    const prt = $c.win.getParent();
    if (prt !== undefined) {

        fn_GetPar = prt.fn_GetPar;
    }

    if (fn_GetPar !== undefined) {
        const arrPar = new Array();

        fn_GetPar(arrPar);
        txb_StdCd.setValue(arrPar[0].STD_CD);
        txb_BndListProcsTpCd.setValue(arrPar[0].BND_LIST_PROCS_TP_CD);
    }
};

/**
 * @method
 * @name gform_onload
 * @description 숨기기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 숨기기
    txb_StdCd.hide();
    txb_BndListProcsTpCd.hide();
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    $c.bns.BnsPanelToGroupBox(pnl_Input);
    // 파라미터설정
    scwin.setParam();
    // 콤보설정
    await scwin.setCombo();
    // 목록조회
    await scwin.search();
};
